<script setup lang="ts">
import { computed, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { Copy, ArrowUp, ArrowDown } from 'lucide-vue-next'
import { purchaseReturnLabels, type PurchaseReturnOrder, type PurchaseReturnStatus } from '@/api/purchase-returns'
import WorkbenchStatusBadge from './WorkbenchStatusBadge.vue'
import OrderProductImage from './OrderProductImage.vue'
import ShippingCountryBadge from './ShippingCountryBadge.vue'
import RecipientDetailsDialog from './RecipientDetailsDialog.vue'
import OrderAmountBreakdown from '@/components/ui/OrderAmountBreakdown.vue'
const props = defineProps<{ rows: PurchaseReturnOrder[]; selected: string[]; disabled?: boolean; paidAtOrder: 'asc' | 'desc' }>()
const emit = defineEmits<{ 'update:selected': [ids: string[]]; copy: [value: string]; sort: [] }>()
const { locale } = useI18n(), zh = computed(() => String(locale.value).startsWith('zh'))
const text = (cn: string, en: string) => zh.value ? cn : en
const recipientId = ref<string>(), recipient = computed(() => props.rows.find(row => row.id === recipientId.value))
const tone = (status: PurchaseReturnStatus) => status === 'completed' || status === 'received' ? 'success' : status === 'pending_outbound' ? 'warning' : status === 'in_transit' ? 'info' : 'neutral'
const date = (value: string | null | undefined) => value && Number.isFinite(Date.parse(value)) ? new Intl.DateTimeFormat('zh-CN', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(value)) : '—'
function toggle(id: string, event: Event) { emit('update:selected', (event.target as HTMLInputElement).checked ? [...props.selected, id] : props.selected.filter(value => value !== id)) }
</script>
<template>
  <div class="table-scroll"><table class="workbench-task-table purchase-return-orders"><thead><tr><th>{{ text('订单编号', 'Order number') }}</th><th>{{ text('商品图片 / 商品信息', 'Product image / details') }}</th><th>{{ text('Shopify 单号', 'Shopify order') }}</th><th>{{ text('订单金额', 'Order amount') }}</th><th>Customer</th><th :aria-sort="paidAtOrder === 'asc' ? 'ascending' : 'descending'"><button class="sort-payment" :disabled="disabled" @click="emit('sort')">{{ text('收款日期', 'Payment date') }}<component :is="paidAtOrder === 'asc' ? ArrowUp : ArrowDown" :size="13" /></button></th><th>{{ text('采购退货', 'Purchase returns') }}</th><th>{{ text('客户名称', 'Customer name') }}</th><th>{{ text('店铺', 'Store') }}</th><th>{{ text('发货仓库', 'Shipping warehouse') }}</th><th>{{ text('业务员', 'Salesperson') }}</th><th>{{ text('订单审核时间', 'Order approval time') }}</th></tr></thead>
    <tbody><tr v-for="row in rows" :key="row.id" class="order-record"><td class="order-cell" :data-label="text('订单编号', 'Order number')"><input type="checkbox" class="order-checkbox" :checked="selected.includes(row.id)" :disabled="disabled" :aria-label="text('选择订单', 'Select order') + ' ' + row.orderNumber" @change="toggle(row.id, $event)"><button class="copy-order" :title="row.orderNumber" :aria-label="text('复制订单编号', 'Copy order number') + ' ' + row.orderNumber" @click="emit('copy', row.orderNumber)"><strong>{{ row.orderNumber }}</strong><Copy :size="13" /></button><span class="multi-item-badge">{{ text(`${row.items.length} 款商品 · ${row.items.reduce((sum, item) => sum + item.quantity, 0)} 件`, `${row.items.length} products · ${row.items.reduce((sum, item) => sum + item.quantity, 0)} units`) }}</span></td>
      <td class="product-cell" :data-label="text('商品图片 / 商品信息', 'Product image / details')"><div v-for="(item, index) in row.items" :key="index" class="product"><OrderProductImage :src="item.imageUrl" :name="item.name" /><div class="product-details"><span class="product-name" :title="item.name">{{ item.name }}</span><div class="product-sku-meta"><button class="copy-value product-sku" @click="emit('copy', item.sku)">{{ item.sku }}<Copy :size="11" /></button><span class="product-quantity">× {{ item.quantity }}</span></div><span class="product-variant">{{ item.variant || '—' }}</span></div></div></td>
      <td :data-label="text('Shopify 单号', 'Shopify order')"><button v-if="row.shopifyOrderNumber" class="copy-value" @click="emit('copy', row.shopifyOrderNumber)">{{ row.shopifyOrderNumber }}<Copy :size="11" /></button><span v-else>—</span></td>
      <td class="amount-cell" :data-label="text('订单金额', 'Order amount')"><OrderAmountBreakdown :amount="row.amount" :currency="row.currency" :breakdown="row.amountBreakdown" /></td>
      <td data-label="Customer"><ShippingCountryBadge :code="row.shippingCountryCode" /><button v-if="row.shippingRecipient" class="recipient-name" @click="recipientId = row.id">{{ row.shippingRecipient.name || text('查看收件人', 'View recipient') }}</button></td>
      <td class="date-cell" :data-label="text('收款日期', 'Payment date')"><span v-for="(part, index) in date(row.paidAt).split(' ')" :key="index">{{ part }}</span></td>
      <td class="return-links-cell" :data-label="text('采购退货', 'Purchase returns')"><div v-for="document in row.purchaseReturns" :key="document.id" class="purchase-return-link"><div class="return-link-heading"><button v-if="document.number" class="copy-value return-bill-number" @click="emit('copy', document.number)">{{ document.number }}<Copy :size="12" /></button><WorkbenchStatusBadge :tone="tone(document.status)">{{ purchaseReturnLabels[document.status][zh ? 0 : 1] }}</WorkbenchStatusBadge></div><div class="return-purchase"><button class="copy-value" @click="emit('copy', document.purchaseOrder.number)">{{ document.purchaseOrder.number }}<Copy :size="11" /></button><span>{{ document.supplier.name }}</span></div><p class="return-quantities">{{ text(`退货 ${document.quantity} 件 · 已退 ${document.returnedQuantity} 件`, `${document.quantity} return units · ${document.returnedQuantity} sent`) }}</p><p class="return-skus" :title="document.lines.map(line => `${line.sku} × ${line.quantity}`).join(' · ')">{{ document.lines.map(line => `${line.sku} × ${line.quantity}`).join(' · ') }}</p><div v-if="document.logistics.carrier || document.logistics.trackingNumber" class="return-logistics"><span>{{ document.logistics.carrier }}</span><button v-if="document.logistics.trackingNumber" class="copy-value" @click="emit('copy', document.logistics.trackingNumber)">{{ document.logistics.trackingNumber }}<Copy :size="11" /></button></div></div></td>
      <td :data-label="text('客户名称', 'Customer name')"><button class="copy-value" @click="emit('copy', row.customerName)">{{ row.customerName }}<Copy :size="11" /></button></td><td :data-label="text('店铺', 'Store')">{{ row.storeName || '—' }}</td><td :data-label="text('发货仓库', 'Shipping warehouse')">{{ row.warehouse || '—' }}</td><td :data-label="text('业务员', 'Salesperson')"><span class="salesperson-name">{{ row.owner?.name || row.salesperson || '—' }}</span><span class="salesperson-department">{{ row.department?.name || '—' }}</span></td><td class="date-cell" :data-label="text('订单审核时间', 'Order approval time')"><span v-for="(part, index) in date(row.reviewedAt).split(' ')" :key="index">{{ part }}</span></td></tr></tbody>
  </table></div>
  <RecipientDetailsDialog v-if="recipient?.shippingRecipient" :recipient="recipient.shippingRecipient" :country-code="recipient.shippingCountryCode" :order-number="recipient.orderNumber" @close="recipientId = undefined" />
</template>
<style scoped>
.table-scroll{overflow-x:auto;min-width:0}table{width:100%;border-collapse:collapse;table-layout:fixed}th{font-weight:600;text-align:left;vertical-align:middle;background:var(--color-surface-muted);white-space:normal}th,td{padding:16px 12px;border-bottom:1px solid var(--color-border)}td{line-height:1.7;vertical-align:middle;overflow-wrap:anywhere}th:nth-child(1){width:11%;text-align:center}.order-cell{text-align:center}.order-cell .multi-item-badge{margin-left:auto;margin-right:auto}th:nth-child(2){width:16%}th:nth-child(3),th:nth-child(4),th:nth-child(10){width:5%}th:nth-child(5){width:6%}th:nth-child(6),th:nth-child(9),th:nth-child(11),th:nth-child(12){width:7%}th:nth-child(7){width:16%}th:nth-child(8){width:8%}.date-cell span{display:inline-block;white-space:nowrap}.date-cell span+span{margin-left:4px}.order-record:nth-child(even){background:color-mix(in srgb,var(--color-surface) 97%,var(--color-text))}.order-cell .copy-order{max-width:calc(100% - 25px)}.copy-order,.copy-value,.sort-payment{display:inline-flex;align-items:center;gap:5px;max-width:100%;text-align:left}.copy-order strong{font-size:12px;color:var(--color-chart-link);white-space:nowrap}.copy-order svg,.copy-value svg{flex-shrink:0;color:var(--color-text-secondary)}.order-checkbox{vertical-align:middle;margin-right:7px}.multi-item-badge{display:block;width:fit-content;margin-top:8px;padding:3px 6px;font-size:10px;color:var(--color-text-secondary);background:var(--color-surface-muted);border-radius:4px}.product{display:flex;gap:10px;align-items:flex-start;margin:8px 0}.product-details{min-width:0}.product-name{display:block;font-size:12px;line-height:1.6}.product-sku-meta{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin-top:6px}.product-sku,.product-variant{font-size:11px;color:var(--color-text-secondary)}.product-quantity{font-size:10px;line-height:1.4;padding:1px 4px;background:var(--color-surface-muted);border-radius:3px}.product-variant{display:block;margin-top:5px}.amount-cell{white-space:nowrap}.recipient-name{display:block;font-size:11px;margin-top:6px;text-align:left}.salesperson-name,.salesperson-department{display:block;line-height:1.65}.salesperson-department{font-size:11px;color:var(--color-text-secondary);margin-top:3px}.return-link-heading{display:flex;align-items:center;flex-wrap:wrap;gap:7px}.return-bill-number{font-size:12px;font-weight:600;color:var(--color-chart-link)}.purchase-return-link+.purchase-return-link{margin-top:12px;padding-top:12px;border-top:1px dashed var(--color-border)}.return-purchase{display:flex;flex-wrap:wrap;align-items:center;gap:7px;font-size:11px;margin-top:7px;color:var(--color-text-secondary)}.return-quantities{font-size:11px;margin-top:5px}.return-skus{font-size:10px;color:var(--color-text-secondary);margin-top:4px;overflow-wrap:anywhere}.return-logistics{display:flex;flex-wrap:wrap;gap:7px;font-size:11px;color:var(--color-text-secondary);margin-top:5px}
@container order-list (max-width:1680px){table,tbody{display:block;width:100%}thead{display:none}.order-record{display:grid;grid-template-columns:minmax(230px,1.15fr) minmax(260px,1fr) repeat(2,minmax(140px,.85fr));padding:16px 20px;gap:18px 22px;border-bottom:1px solid var(--color-border)}.order-record td{display:block;padding:0;border:0;background:transparent;min-width:0}.order-record td::before{content:attr(data-label);display:block;font-size:10px;font-weight:500;color:var(--color-text-secondary);margin-bottom:7px}.order-record .order-cell{grid-column:1/-1;display:flex;flex-wrap:wrap;align-items:center;gap:10px;padding-bottom:12px;border-bottom:1px solid var(--color-border)}.order-record .order-cell::before{display:none}.order-cell .multi-item-badge{margin:0 0 0 auto}.order-record .product-cell{grid-column:1;grid-row:2/span 5}.order-record .return-links-cell{grid-column:2;grid-row:2/span 5}.order-record .amount-cell{padding-left:8px}}
@container order-list (max-width:950px){.order-record{grid-template-columns:repeat(2,minmax(0,1fr));padding:16px;gap:18px}.order-record .product-cell,.order-record .return-links-cell{grid-column:1/-1;grid-row:auto}}
@container order-list (max-width:400px){.order-record{grid-template-columns:minmax(0,1fr)}}
</style>
